 s=one(s,'</style>',CSS+'</style>');s=one(s,"function nav(dest){tab=dest;fb='';draw()}","const entered=lessons.map(()=>false),reveal=lessons.map(()=>0); function nav(dest){tab=(dest==='practice'&&!entered[li])?'intro':dest;fb='';draw()}")
 s=one(s,"function pick(i){li=i;tab='intro';ip=0;fb='';draw()}","function pick(i){li=i;tab='intro';ip=0;reveal[i]=0;fb='';draw()}")
 a=s.index("if(tab==='intro')");b=s.index("if(tab==='practice')",a);s=s[:a]+INTRO+s[b:];a=s.index("if(tab==='theory')");b=s.index("if(tab==='verb')",a);s=s[:a]+THEORY+s[b:]
 s=one(s,"else if(a==='launch'||a==='back')nav('practice');else if(a==='prevIntro'||a==='nextIntro'){ip+=a==='nextIntro'?1:-1;draw()}","else if(a==='launch'){if(ip===L().intro.length-1){entered[li]=true;nav('practice');document.getElementById('tabs').scrollIntoView({block:'start'})}}else if(a==='back')nav('practice');else if(a==='nextIntro'){ip=Math.min(ip+1,L().intro.length-1);reveal[li]=ip;draw();const card=document.querySelector('[data-reveal]');if(card){card.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});const b=card.querySelector('button');if(b)b.focus({preventScroll:true})}}")
 s=one(s,'if(!el)return;if(el.dataset.lang)',"if(!el){if(tab==='intro'&&e.target.closest('.stack')&&!window.getSelection()?.toString())document.querySelector('[data-a=nextIntro]')?.click();return;}if(el.dataset.lang)");s=s.replace("intro:T('Интро','Вступ')","intro:T('Вступление','Вступ')")
 return s
